from __future__ import annotations

from datetime import datetime

from sqlalchemy import DateTime, Float, ForeignKey, Integer, JSON, String, Text
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.models.base import Base
from app.models.enums import AlertStatus
from app.models.user import utcnow


class Alert(Base):
    """Investigation alert generated by the cross-domain intelligence engine."""

    __tablename__ = "alerts"

    id: Mapped[int] = mapped_column(primary_key=True)
    type: Mapped[str] = mapped_column(String(40), index=True, nullable=False)
    title: Mapped[str] = mapped_column(String(300), nullable=False)
    interpretation: Mapped[str | None] = mapped_column(Text, nullable=True)
    disclaimer: Mapped[str | None] = mapped_column(Text, nullable=True)

    score: Mapped[float] = mapped_column(Float, default=0.0, nullable=False)
    districts: Mapped[list | None] = mapped_column(JSON, nullable=True)
    complaint_categories: Mapped[list | None] = mapped_column(JSON, nullable=True)
    n_complaints: Mapped[int] = mapped_column(Integer, default=0, nullable=False)
    n_reports: Mapped[int] = mapped_column(Integer, default=0, nullable=False)
    n_supporting_pairs: Mapped[int] = mapped_column(Integer, default=0, nullable=False)
    evidence: Mapped[list | None] = mapped_column(JSON, nullable=True)

    status: Mapped[str] = mapped_column(String(20), default=AlertStatus.NEW.value,
                                        index=True, nullable=False)
    status_note: Mapped[str | None] = mapped_column(Text, nullable=True)
    reviewed_by_id: Mapped[int | None] = mapped_column(ForeignKey("users.id"), nullable=True)

    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=utcnow,
                                                 index=True, nullable=False)
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=utcnow,
                                                 onupdate=utcnow, nullable=False)

    investigations = relationship("Investigation", back_populates="alert")
